/// <summary>
/// One question of the D365 Data Quiz. The correct option stays on the server: <c>toJson</c> does not include it.
/// </summary>
public class DEVTutorialArcadeQuizQuestion
{
    str       questionId;
    int       questionNum;
    str       category;
    str       text;
    container choices;
    int       correctIndex;
    str       explanation;
    str       xppQuery;
    boolean   answered;
    int       answer;
    boolean   fiftyUsed;
    int       points;
}

Method.Source:
/// <summary>
/// Creates a question with the right answer and three wrong ones in random order.
/// </summary>
/// <param name = "_category">Category shown above the question, e.g. SALES.</param>
/// <param name = "_text">The question.</param>
/// <param name = "_correct">The right answer.</param>
/// <param name = "_wrong">Three wrong answers.</param>
/// <param name = "_explanation">Shown after answering.</param>
/// <param name = "_xppQuery">The X++ statement that produced the answer, shown after answering.</param>
/// <returns>The question.</returns>
public static DEVTutorialArcadeQuizQuestion construct(str _category, str _text, str _correct, container _wrong, str _explanation, str _xppQuery)
{
    DEVTutorialArcadeQuizQuestion question = new DEVTutorialArcadeQuizQuestion();
    container options = [_correct];
    int i;

    for (i = 1; i <= 3; i++)
    {
        options += conPeek(_wrong, i);
    }
    options = DEVTutorialArcadeQuizEngine::shuffle(options);

    question.category     = _category;
    question.text         = _text;
    question.choices      = options;
    question.correctIndex = conFind(options, _correct) - 1;
    question.explanation  = _explanation;
    question.xppQuery     = _xppQuery;

    return question;
}

/// <summary>
/// Returns the question for the browser, without the correct answer.
/// </summary>
/// <param name = "_total">Number of questions in the quiz.</param>
/// <returns>JSON: id, index, total, category, text, options, seconds.</returns>
public str toJson(int _total)
{
    return DEVTutorialArcadeJson::object([
        DEVTutorialArcadeJson::pair('id', DEVTutorialArcadeJson::quote(questionId)),
        DEVTutorialArcadeJson::pair('index', int2Str(questionNum)),
        DEVTutorialArcadeJson::pair('total', int2Str(_total)),
        DEVTutorialArcadeJson::pair('category', DEVTutorialArcadeJson::quote(category)),
        DEVTutorialArcadeJson::pair('text', DEVTutorialArcadeJson::quote(text)),
        DEVTutorialArcadeJson::pair('options', DEVTutorialArcadeJson::stringArray(choices)),
        DEVTutorialArcadeJson::pair('seconds', int2Str(DEVTutorialArcadeQuizEngine::Seconds))]);
}

/// <summary>
/// Gets the text of an option.
/// </summary>
/// <param name = "_index">0-based option index.</param>
/// <returns>The option text; empty for an invalid index.</returns>
public str choiceText(int _index)
{
    return _index >= 0 && _index < conLen(choices) ? any2Str(conPeek(choices, _index + 1)) : '';
}

public str parmQuestionId(str _questionId = questionId)
{
    questionId = _questionId;
    return questionId;
}

public int parmQuestionNum(int _questionNum = questionNum)
{
    questionNum = _questionNum;
    return questionNum;
}

public boolean parmAnswered(boolean _answered = answered)
{
    answered = _answered;
    return answered;
}

public int parmAnswer(int _answer = answer)
{
    answer = _answer;
    return answer;
}

public boolean parmFiftyUsed(boolean _fiftyUsed = fiftyUsed)
{
    fiftyUsed = _fiftyUsed;
    return fiftyUsed;
}

public int parmPoints(int _points = points)
{
    points = _points;
    return points;
}
